const cfg = $('Config').first().json;
const client = String(cfg.client_name || cfg.environment_name || '');
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const node = n => { try { return $(n).first().json; } catch (e) { return null; } };
const num = v => { const x = parseFloat(String(v ?? '').replace(/'/g, '')); return isNaN(x) ? 0 : x; };
const thr = (v, w, c) => (v >= c ? 'CRIT' : v >= w ? 'WARN' : 'OK');
const GB = 1073741824;
const checks = [];
const add = (area, name, status, detail, fix = '') => checks.push({ area, name, status, detail, fix });
const jparse = lines => { try { return JSON.parse((lines || []).join('')); } catch (e) { return null; } };
const kv = lines => { const o = {}; (lines || []).forEach(l => { const m = l.match(/^([a-z_0-9]+)='?([^']*)'?$/); if (m) o[m[1]] = m[2]; }); return o; };
const dur = s => (s >= 172800 ? Math.round(s / 86400) + ' d' : Math.round(s / 3600) + ' h');

function parse(out) {
  const k = {}, b = {}, r = {}; let cur = null;
  for (const line of String(out).split('\n')) {
    if (cur) { if (line === 'E|' + cur) cur = null; else b[cur].push(line); continue; }
    if (line.startsWith('B|')) { cur = line.slice(2); b[cur] = []; }
    else if (line.startsWith('K|')) { const i = line.indexOf('|', 2); k[line.slice(2, i)] = line.slice(i + 1); }
    else if (line.startsWith('SVC|')) (r.SVC = r.SVC || []).push(line.split('|').slice(1));
  }
  return { k, b, r };
}

// ---------- collect SSH results (a disabled SSH node just passes data through, so de-duplicate by host) ----------
const SSH_NODES = ['SSH Wazuh Server', 'SSH Indexer Host', 'SSH Dashboard Host'];
const hosts = new Map(); const sshFail = new Map();
for (const n of SSH_NODES) {
  const j = node(n); if (!j) continue;
  if (typeof j.stdout === 'string' && j.stdout.includes('K|HOST|')) { const p = parse(j.stdout); if (!hosts.has(p.k.HOST)) hosts.set(p.k.HOST, p); }
  else {
    const msg = String(typeof j.error === 'string' ? j.error : (j.error && j.error.message) || (j.stderr ? j.stderr : 'no output')).slice(0, 160);
    if (!sshFail.has(msg)) sshFail.set(msg, n);
  }
}

const FIX = {
  ssh: 'Check SSH reachability from the n8n host (port 22, firewall), the SSH user/key in the n8n credential, and that the account can log in non-interactively.',
  priv: 'Use root, or a user with passwordless sudo (NOPASSWD) for the SSH credential. Without it most checks cannot read /var/ossec, journals or certificates.',
  svc: s => `systemctl status ${s} --no-pager -l ; journalctl -u ${s} -n 100 --no-pager ; then systemctl restart ${s}`,
  daemons: 'Run /var/ossec/bin/wazuh-control status, then systemctl restart wazuh-manager and read /var/ossec/logs/ossec.log for the reason the daemon stopped.',
  conf: 'Run /var/ossec/bin/wazuh-analysisd -t to see the exact error in ossec.conf, rules or decoders. Fix it BEFORE the next restart or the manager will not start.',
