const sc = { OK: '#16a34a', WARN: '#d97706', ERROR: '#7c3aed', CRIT: '#dc2626', 'N/A': '#9ca3af' };
const eFont = "-apple-system,'Segoe UI',Helvetica,Arial,sans-serif";
const cut = (s, n) => { s = String(s || ''); return s.length > n ? s.slice(0, n).replace(/\s+\S*$/, '') + ' ... (full steps in the PDF)' : s; };
const cap = t => `<div style="font-family:${eFont};font-size:11px;font-weight:600;letter-spacing:1.5px;color:#9ca3af;text-transform:uppercase;">${t}</div>`;
const dot = col => `<span style="color:${col};font-size:13px;">&#9679;</span>`;
const brand = esc(cfg.brand_name || 'YOUR COMPANY'), brandSub = esc(cfg.brand_subtitle || 'SECURITY OPERATIONS');
const brandLine = cfg.brand_logo_url ? `<img src="${esc(cfg.brand_logo_url)}" alt="${brand}" height="24" style="display:block;border:0;height:24px;">`
  : `<div style="font-family:${eFont};font-size:11px;font-weight:700;letter-spacing:2px;color:#111827;">${brand} <span style="color:#9ca3af;font-weight:500;">&nbsp;${brandSub}</span></div>`;
const topCol = sc[overall];
const statusWord = overall === 'OK' ? 'Healthy' : overall === 'CRIT' ? 'Critical' : 'Warning';
const statusText = issues.length ? `${nCrit ? nCrit + ' critical' : ''}${nCrit && nWarn ? ', ' : ''}${nWarn ? nWarn + ' warning' + (nWarn > 1 ? 's' : '') : ''} &middot; ${checks.length} checks` : `All ${checks.length} checks passed`;
const comps = areas.map(a => `<span style="white-space:nowrap;margin-right:16px;">${dot(sc[areaStatus(a)])} <span style="color:#374151;">${a}</span></span>`).join(' ');
const maxDisk = serverRows.length ? serverRows.map(s => esc(s.disk)).join(' / ') : 'n/a';
const stats = [[agentSnap ? `${agentSnap.active}/${agentSnap.total}` : 'n/a', 'Active agents'], [cnt24 === null ? 'n/a' : cnt24.toLocaleString('en-US'), 'Alerts 24h'], [cnt24 === null ? 'n/a' : highSev.toLocaleString('en-US'), 'High severity'], [maxDisk, 'Disk used']]
  .map(([v, l]) => `<td class="stat" width="25%" valign="top" style="font-family:${eFont};"><div style="font-size:20px;font-weight:700;color:#111827;">${esc(v)}</div><div style="font-size:11px;color:#9ca3af;margin-top:2px;">${l}</div></td>`).join('');
const shown = issues.slice(0, 8);
const eRows = shown.map((i, n) => `<tr><td style="padding:14px 0;${n ? 'border-top:1px solid #eef0f3;' : ''}font-family:${eFont};">
<div style="font-size:14px;font-weight:600;color:#111827;">${dot(sc[i.status])}&nbsp; ${esc(i.name)}${i.isNew ? ' <span style="font-size:10px;font-weight:700;color:#2563eb;letter-spacing:.5px;">NEW</span>' : ''} <span style="font-size:12px;font-weight:400;color:#9ca3af;">&nbsp;${esc(i.area)} &middot; ${label[i.status].toLowerCase()}</span></div>
<div style="font-size:13px;line-height:1.55;color:#4b5563;margin:5px 0 0 22px;">${esc(i.detail)}</div>
${i.fix ? `<div style="font-size:12.5px;line-height:1.55;color:#6b7280;margin:6px 0 0 22px;"><span style="color:#111827;font-weight:600;">Action:</span> ${esc(cut(i.fix, 220))}</div>` : ''}
</td></tr>`).join('');
const moreIssues = issues.length > shown.length ? `<tr><td style="padding:10px 0 0;border-top:1px solid #eef0f3;font-family:${eFont};font-size:12px;color:#9ca3af;">+ ${issues.length - shown.length} more in the attached PDF</td></tr>` : '';
const issuesBlock = issues.length ? `<table width="100%" cellpadding="0" cellspacing="0" role="presentation">${eRows}${moreIssues}</table>` : `<div style="font-family:${eFont};font-size:14px;color:#374151;padding:6px 0;">${dot(sc.OK)}&nbsp; No issues found.</div>`;
const resolvedLine = resolved.length ? `<tr><td style="padding:4px 36px 0;font-family:${eFont};font-size:12.5px;line-height:1.6;color:#16a34a;">Resolved since last run: ${resolved.map(esc).join(', ')}</td></tr>` : '';
const EW = Math.max(480, Math.min(1100, num(cfg.email_width) || 820));
const emailHtml = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>@media only screen and (max-width:600px){.px{padding-left:18px!important;padding-right:18px!important}.stat{display:block!important;width:50%!important;float:left;padding-bottom:12px}}</style></head>
<body style="margin:0;padding:0;background:#f5f6f8;"><table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="background:#f5f6f8;"><tr><td align="center" style="padding:32px 12px;">
<!--[if mso]><table role="presentation" width="${EW}" align="center" cellpadding="0" cellspacing="0"><tr><td><![endif]-->
<table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="width:100%;max-width:${EW}px;background:#ffffff;border:1px solid #e6e8ec;border-top:4px solid ${topCol};border-radius:8px;">
<tr><td class="px" style="padding:28px 36px 0;">${brandLine}
<div style="font-family:${eFont};font-size:26px;font-weight:700;color:#111827;margin-top:18px;">Wazuh Healthcheck</div>
<div style="font-family:${eFont};font-size:13px;color:#9ca3af;margin-top:4px;">${esc(client)} &middot; ${when}${version !== 'n/a' ? ' &middot; ' + esc(version) : ''}</div></td></tr>
<tr><td class="px" style="padding:20px 36px 0;font-family:${eFont};"><span style="font-size:16px;font-weight:700;color:${topCol};">${dot(topCol)}&nbsp; ${statusWord}</span><span style="font-size:14px;color:#6b7280;">&nbsp;&nbsp;${statusText}</span></td></tr>
<tr><td class="px" style="padding:12px 36px 0;font-family:${eFont};font-size:12.5px;line-height:2;">${comps}</td></tr>
<tr><td class="px" style="padding:24px 36px 0;"><table width="100%" cellpadding="0" cellspacing="0" role="presentation" style="border-top:1px solid #eef0f3;border-bottom:1px solid #eef0f3;"><tr><td style="padding:16px 0;"><table width="100%" cellpadding="0" cellspacing="0" role="presentation"><tr>${stats}</tr></table></td></tr></table></td></tr>
<tr><td class="px" style="padding:24px 36px 6px;">${cap(issues.length ? 'Issues (' + issues.length + ')' : 'Issues')}</td></tr>
<tr><td class="px" style="padding:0 36px;">${issuesBlock}</td></tr>
${resolvedLine}
<tr><td class="px" style="padding:26px 36px 28px;font-family:${eFont};font-size:11.5px;color:#9ca3af;">Full report attached as PDF.<!--PDFNOTE--></td></tr>
</table>
<!--[if mso]></td></tr></table><![endif]-->
</td></tr></table></body></html>`;

const bin = await this.helpers.prepareBinaryData(Buffer.from(html, 'utf8'), 'index.html', 'text/html');
return [{ json: { overall, counts, when, subject, emailHtml, issueCount: issues.length, headline }, binary: { data: bin } }];
